import pyomo.environ as pyo

DATA = {
    "products": ["scooter", "bike"],
    "resources": ["design", "engineering"],
    "profit": {"scooter": 200, "bike": 300},
    "usage": {
        "design": {"scooter": 2, "bike": 4},
        "engineering": {"scooter": 3, "bike": 5},
    },
    "capacity": {"design": 5000, "engineering": 6000},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    # Decision: whole units produced per month
    model.production = pyo.Var(
        model.P, within=pyo.NonNegativeIntegers, bounds=(0, None)
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # One capacity constraint per resource
    def capacity_rule(m, r):
        return sum(d["usage"][r][p] * m.production[p] for p in m.P) <= d["capacity"][r]

    model.capacity = pyo.Constraint(model.R, rule=capacity_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "products": ["scooter", "bike"],
    "resources": ["design", "engineering"],
    "profit": {"scooter": 200, "bike": 300},
    # usage[resource][product] = hours of resource per unit of product
    "usage": {
        "design": {"scooter": 2, "bike": 4},
        "engineering": {"scooter": 3, "bike": 5},
    },
    "capacity": {"design": 5000, "engineering": 6000},
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    # Decision: units produced per product per month
    model.production = pyo.Var(
        model.P, within=pyo.NonNegativeIntegers, bounds=(0, None)
    )

    # Objective: maximize total profit
    def obj_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.maximize)

    # Resource capacity constraints (one per resource)
    def capacity_rule(m, r):
        return sum(
            d["usage"][r][p] * m.production[p] for p in m.P
        ) <= d["capacity"][r]

    model.resource_capacity = pyo.Constraint(model.R, rule=capacity_rule)

    return model
